package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.ErrorCode;
import com.ruoyi.medical.workflow.WorkflowProtocol;
import com.ruoyi.medical.workflow.TaskRunWaitingProtocol.WaitingCompletionV2;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;

/** Separate V2 control completion. No StepResult/artifact is synthesized and the
 * immutable V1 runtime receipt schema is never overloaded. */
public final class TaskRunWaitingCommitService {
    static final String ACTION="task.run.waiting.committed.v2";private static final Contract CONTRACT=contract();static final String MANIFEST=CONTRACT.manifest();
    private final JdbcTemplate db;private final PermissionSchema json;private final TaskRuntimeJournal runtime;
    private final TaskRegisteredToolWaitingCompletion producers;private final TaskRunWorkflowProtocolBinding protocols;private final TaskRunActivityJournal journal;
    private final JsonMapper reader=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
    public TaskRunWaitingCommitService(DataSource data,PermissionSchema json,TaskRuntimeJournal runtime,TaskRegisteredToolWaitingCompletion producers,TaskRunWorkflowProtocolBinding protocols){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.runtime=runtime;this.producers=producers;this.protocols=protocols;journal=new TaskRunActivityJournal(db,json);}
    WorkflowProtocol.Receipt commit(FormalTaskNodeAuthority.Verified node,WorkflowProtocol.Dispatch dispatch,WaitingCompletionV2 completion)throws Exception{
        node.requireUnchanged();var a=node.controlAdmission();if(!a.controlWorker()||!TransactionSynchronizationManager.isActualTransactionActive())deny();var input=node.currentInput();same(input.runId(),dispatch.runId());same(input.stepId(),dispatch.stepId());same(input.inputSha256(),dispatch.inputSha256());require(dispatch,completion);
        var protocol=protocols.requireWaitingV2(a,dispatch.runId());same(dispatch,runtime.requireExistingStep(node,new ProfessionalRuntimeObservations.Binding(input.tenantId(),dispatch.runId(),dispatch.stepId(),dispatch.actionId(),dispatch.leaseGeneration(),dispatch.inputSha256(),dispatch.stepEnvelopeSha256())));
        var row=run(a,input.projectId(),dispatch.runId());var step=step(a,input.projectId(),dispatch.runId(),dispatch.stepId());
        if(!db.queryForList("SELECT receipt_id FROM run_runtime_receipt WHERE tenant_id=? AND project_id=? AND run_id=? AND command_id=? LIMIT 2 FOR UPDATE",input.tenantId(),input.projectId(),dispatch.runId(),dispatch.commandId()).isEmpty())bad();
        var produced=producers.requireProduced(node,dispatch,completion);produced.requireUnchanged();same(text(row,"classification"),produced.classification());var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));if(now.isBefore(produced.createdAt()))bad();var request=produced.canonicalCommitRequest();checkRequest(dispatch,completion,request);same(produced.waitingItemId(),request.required("waiting_item_id").asText());
        var receipt=new WorkflowProtocol.Receipt(dispatch.stepId(),dispatch.inputSha256(),dispatch.leaseGeneration(),WorkflowProtocol.State.WAITING_INPUT,id(dispatch.commandId()),produced.waitingItemId(),List.of());
        var witness=witness(dispatch,completion,request,receipt,protocol.protocolSha256());var existing=journal.read(a,input.projectId(),dispatch.runId(),receipt.receiptId(),ACTION,key(dispatch.commandId()),dispatch.commandId(),journal.hash(request),text(row,"classification"),"2.0.0",MANIFEST);
        if(existing.isPresent()){same(json.canonical(witness),json.canonical(existing.get()));verifyStep(step,receipt);return receipt;}
        same("RUNNING",text(row,"status"));if(row.get("ended_at")!=null||row.get("dispatch_closed_at")!=null)deny();same("RUNNING",text(step,"status"));same(dispatch.inputSha256(),text(step,"input_sha256"));same(Long.toString(dispatch.leaseGeneration()),number(step,"lease_generation"));same(produced.stepRevision().toString(),number(step,"revision"));
        var attempt=one(db.queryForList("SELECT worker_service_uri FROM step_runtime_attempt WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND lease_generation=? LIMIT 2 FOR UPDATE",input.tenantId(),input.projectId(),dispatch.runId(),dispatch.stepId(),dispatch.leaseGeneration()));same(text(attempt,"worker_service_uri"),text(step,"lease_owner"));
        produced.requireUnchanged();protocol.requireUnchanged();node.requireUnchanged();
        journal.write(a,input.projectId(),dispatch.runId(),receipt.receiptId(),ACTION,key(dispatch.commandId()),dispatch.commandId(),journal.hash(request),text(row,"classification"),"2.0.0",MANIFEST,witness);
        changed(db.update("UPDATE run_step SET status='WAITING_INPUT',output_ref='[]',revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND status='RUNNING' AND revision=? AND lease_generation=? AND lease_owner=? AND lease_expires_at>UTC_TIMESTAMP(6) AND input_sha256=?",input.tenantId(),input.projectId(),dispatch.runId(),dispatch.stepId(),produced.stepRevision(),dispatch.leaseGeneration(),text(attempt,"worker_service_uri"),dispatch.inputSha256()));
        return receipt;
    }
    Optional<WorkflowProtocol.Receipt> loadCommitted(EnterpriseAccess.Admission a,String runId,String stepId)throws Exception{
        recovery(a,runId);var identity=a.recoveryProof().identity();var rows=db.queryForList("SELECT response_ref FROM operation_record WHERE tenant_id=? AND subject_id=? AND target_id=? AND operation_name=? AND response_ref->>'$.request.step_id'=? LIMIT 2 FOR UPDATE",identity.tenantId(),identity.actorId(),runId,ACTION,stepId);if(rows.isEmpty())return Optional.empty();var raw=reader.readTree(text(one(rows),"response_ref"));var c=reader.treeToValue(raw.required("completion"),WaitingCompletionV2.class);same(runId,c.runId());same(stepId,c.stepId());var dispatch=runtime.readHistoricalStep(a,runId,stepId,c.leaseGeneration());return Optional.of(recover(a,dispatch,c));
    }
    WorkflowProtocol.Receipt recover(EnterpriseAccess.Admission a,WorkflowProtocol.Dispatch dispatch,WaitingCompletionV2 completion)throws Exception{
        recovery(a,dispatch.runId());require(dispatch,completion);same(dispatch,runtime.requireHistoricalStep(a,dispatch));var identity=a.recoveryProof().identity();var original=producers.requireOriginal(a,completion);var request=original.canonicalCommitRequest();checkRequest(dispatch,completion,request);
        var protocol=protocols.requireWaitingV2(a,dispatch.runId());var row=run(a,identity.projectId(),dispatch.runId());
        var receipt=new WorkflowProtocol.Receipt(dispatch.stepId(),dispatch.inputSha256(),dispatch.leaseGeneration(),WorkflowProtocol.State.WAITING_INPUT,id(dispatch.commandId()),original.waitingItemId(),List.of());
        var expected=witness(dispatch,completion,request,receipt,protocol.protocolSha256());var value=journal.read(a,identity.projectId(),dispatch.runId(),receipt.receiptId(),ACTION,key(dispatch.commandId()),dispatch.commandId(),journal.hash(request),text(row,"classification"),"2.0.0",MANIFEST).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));same(json.canonical(expected),json.canonical(value));verifyStep(step(a,identity.projectId(),dispatch.runId(),dispatch.stepId()),receipt);protocol.requireUnchanged();a.recoveryProof().requireActive();return receipt;
    }
    /** Original committed control fact under exact lifecycle authority, not a new producer. */
    Optional<WorkflowProtocol.Receipt> loadLifecycleCommitted(TaskRunLifecycleAuthority.Proof p,String stepId)throws Exception{
        p.require(p.operation());var a=p.admission();var ref=p.reference();
        var rows=db.queryForList("SELECT response_ref FROM operation_record WHERE tenant_id=? AND subject_id=? AND target_id=? AND operation_name=? AND response_ref->>'$.request.step_id'=? LIMIT 2 FOR UPDATE",ref.tenantId(),a.actorId(),ref.runId(),ACTION,stepId);if(rows.isEmpty())return Optional.empty();
        var raw=reader.readTree(text(one(rows),"response_ref"));if(!CONTRACT.schema().validate(raw).isEmpty())bad();var completion=reader.treeToValue(raw.required("completion"),WaitingCompletionV2.class);same(ref.runId(),completion.runId());same(stepId,completion.stepId());
        var dispatch=runtime.readLifecycleStep(p,stepId,completion.leaseGeneration());same(json.canonical(json.tree(dispatch)),json.canonical(raw.required("dispatch")));require(dispatch,completion);var request=raw.required("request");checkRequest(dispatch,completion,request);
        var receipt=reader.treeToValue(raw.required("receipt"),WorkflowProtocol.Receipt.class);same(WorkflowProtocol.State.WAITING_INPUT,receipt.status());same(id(dispatch.commandId()),receipt.receiptId());same(request.required("waiting_item_id").asText(),receipt.waitingItemId());if(!receipt.outputs().isEmpty())bad();
        var protocol=protocols.requireWaitingV2(a,ref.runId());var expected=witness(dispatch,completion,request,receipt,protocol.protocolSha256());var saved=journal.read(a,ref.projectId(),ref.runId(),receipt.receiptId(),ACTION,key(dispatch.commandId()),dispatch.commandId(),journal.hash(request),p.classification(),"2.0.0",MANIFEST).orElseThrow();same(json.canonical(expected),json.canonical(saved));verifyStep(step(a,ref.projectId(),ref.runId(),stepId),receipt);protocol.requireUnchanged();p.require(p.operation());return Optional.of(receipt);
    }
    /** Answer linkage reads the original writer's journals without substituting
     * the human admission's actor or giving that human scheduler authority. */
    JsonNode requireAnswerOriginal(TaskRegisteredToolWaitingAnswerAuthority.Original p,WaitingCompletionV2 completion)throws Exception{
        p.requireUnchanged();var a=p.admission();if(a.controlWorker()||a.formalWorker()||a.recoveryWorker()||a.simulationWorker())deny();same(p.tenantId(),a.context().tenant_id());
        var dispatch=p.originalDispatch();same(p.runId(),dispatch.runId());require(dispatch,completion);var request=p.canonicalCommitRequest();checkRequest(dispatch,completion,request);
        var receipt=new WorkflowProtocol.Receipt(dispatch.stepId(),dispatch.inputSha256(),dispatch.leaseGeneration(),WorkflowProtocol.State.WAITING_INPUT,id(dispatch.commandId()),p.waitingItemId(),List.of());
        var expected=witness(dispatch,completion,request,receipt,p.protocolSha256());
        var value=journal.readOriginalActor(a,p.originalActorId(),p.projectId(),p.runId(),receipt.receiptId(),ACTION,key(dispatch.commandId()),dispatch.commandId(),journal.hash(request),p.classification(),"2.0.0",MANIFEST).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));
        same(json.canonical(expected),json.canonical(value));var historicalStep=step(a,p.projectId(),p.runId(),dispatch.stepId());same(dispatch.inputSha256(),text(historicalStep,"input_sha256"));same(Long.toString(dispatch.leaseGeneration()),number(historicalStep,"lease_generation"));if(!Set.of("WAITING_INPUT","FAILED","CANCELLED").contains(text(historicalStep,"status")))deny();p.requireUnchanged();return value.deepCopy();
    }
    private JsonNode witness(WorkflowProtocol.Dispatch d,WaitingCompletionV2 c,JsonNode request,WorkflowProtocol.Receipt r,String protocol){var n=json.object().put("schema_version","2.0.0").put("kind","TASK_WAITING_COMMITTED").put("protocol_sha256",protocol);n.set("dispatch",json.tree(d));n.set("completion",json.tree(c));n.set("request",request);n.set("receipt",json.tree(r));if(!CONTRACT.schema().validate(n).isEmpty())bad();return n;}
    private void checkRequest(WorkflowProtocol.Dispatch d,WaitingCompletionV2 c,JsonNode request)throws Exception{same("2.0.0",request.required("schema_version").asText());same("TASK_TOOL_WAITING_COMMIT",request.required("kind").asText());same(d.runId(),request.required("run_id").asText());same(d.stepId(),request.required("step_id").asText());same(d.inputSha256(),request.required("input_sha256").asText());same(d.leaseGeneration(),request.required("lease_generation").longValue());same(journal.hash(json.tree(d)),request.required("dispatch_sha256").asText());same(c.waitingReceiptId(),request.required("producer_receipt_id").asText());same(c.waitingReceiptSha256(),request.required("producer_receipt_sha256").asText());if(!request.required("outputs").isArray()||!request.required("outputs").isEmpty())bad();}
    private void verifyStep(Map<String,Object> step,WorkflowProtocol.Receipt receipt)throws Exception{same("WAITING_INPUT",text(step,"status"));same(receipt.inputSha256(),text(step,"input_sha256"));same(Long.toString(receipt.leaseGeneration()),number(step,"lease_generation"));same(json.tree(List.of()),reader.readTree(text(step,"output_ref")));}
    private Map<String,Object> run(EnterpriseAccess.Admission a,String project,String run){return one(db.queryForList("SELECT * FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? AND created_by=? AND execution_kind='TASK' LIMIT 2 FOR UPDATE",a.context().tenant_id(),project,run,a.actorId()));}
    private Map<String,Object> step(EnterpriseAccess.Admission a,String project,String run,String step){return one(db.queryForList("SELECT * FROM run_step WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),project,run,step));}
    private static void require(WorkflowProtocol.Dispatch d,WaitingCompletionV2 c){same(d.runId(),c.runId());same(d.stepId(),c.stepId());same(d.inputSha256(),c.inputSha256());same(d.leaseGeneration(),c.leaseGeneration());}
    private static void recovery(EnterpriseAccess.Admission a,String run){if(!a.recoveryWorker()||!TransactionSynchronizationManager.isActualTransactionActive())deny();a.recoveryProof().requireActive();same(run,a.recoveryProof().identity().runId());}
    private static String id(String command){return derived(command,ACTION);}private static String key(String command){return "task-waiting-commit-v2:"+command;}
    private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private record Contract(String manifest,com.networknt.schema.JsonSchema schema){}
    private static Contract contract(){try(var in=Objects.requireNonNull(TaskRunWaitingCommitService.class.getResourceAsStream("/task-run-waiting-commit-v2.schema.json"))){byte[] bytes=in.readAllBytes();var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(com.networknt.schema.SchemaLocation.of("https://schemas.medical-agent.invalid/task-run-waiting-commit-v2.schema.json"),new JsonMapper().readTree(bytes),com.networknt.schema.SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());schema.initializeValidators();return new Contract(org.apache.commons.codec.digest.DigestUtils.sha256Hex(bytes),schema);}catch(java.io.IOException e){throw new IllegalStateException(e);}}
}
